// «Docker турших самбар». Энэ файлыг өөрчлөх шаардлагагүй.
const output = document.getElementById("output");
function panel(cls, testid, title, lines) {
  const box = document.createElement("section");
  box.className = "call " + cls;
  box.dataset.testid = testid;
  const h = document.createElement("h2");
  h.textContent = title;
  box.append(h);
  for (const line of lines) {
    const p = document.createElement("pre");
    p.textContent = line;
    box.append(p);
  }
  output.append(box);
  return box;
}

const prev = ["FROM node:20", "COPY package.json .", "RUN npm install", "COPY . .", "CMD npm start"];
// Зөвхөн эх код өөрчлөгдсөн (COPY . .) — 4 дэх алхам.
const next = ["FROM node:20", "COPY package.json .", "RUN npm install", "COPY src .", "CMD npm start"];

window.PLAN = null;
try {
  window.PLAN = planRebuild(prev, next);
  panel("ok", "plan", "Дахин угсрах төлөвлөгөө", [JSON.stringify(window.PLAN, null, 2)]);
} catch (problem) {
  panel("bad", "error", "Алдаа", [problem.message]);
}
document.body.dataset.ready = "1";

