function planRebuild(prev, next) {
  const out = [];
  let changed = false;

  for (let i = 0; i < next.length; i++) {
    if (!changed && prev[i] === next[i]) {
      out.push({ step: next[i], status: "cached" });
    } else {
      changed = true;
      out.push({ step: next[i], status: "rebuilt" });
    }
  }

  return out;
}
